import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.Drawable;
import android.graphics.drawable.LayerDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Global real stars. Foreground explicit playback uses the same bounded native review adapter. */
public final class FavoriteSoundsActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final List<Binding> bindings=new ArrayList<>();private final Map<String,Long> positions=new HashMap<>();private Records.Factory records;private ClipPlaybackPort port;private ClipReviewPlayer player;private ClipReviewPlayer.State playback;private FavoriteSoundRows.Page data;private String category="all",selected="",error="",notice="";private int days,page,generation;private boolean loaded,busy,resumed;private Dialog dialog;
    private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(player!=null)player.stop();}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);records=Records.factory;port=ClipPlayback.provider.create(getApplicationContext(),records);player=new ClipReviewPlayer(port,this::playback);if(saved!=null){category=saved.getString("category","all");days=saved.getInt("days");page=saved.getInt("page");selected=saved.getString("selected","");ArrayList<String> keys=saved.getStringArrayList("positionKeys");long[] values=saved.getLongArray("positions");if(keys!=null&&values!=null)for(int n=0;n<Math.min(keys.size(),values.length);n++)positions.put(keys.get(n),values[n]);}androidx.core.content.ContextCompat.registerReceiver(this,noisy,new IntentFilter(android.media.AudioManager.ACTION_AUDIO_BECOMING_NOISY),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);load();}
    @Override protected void onResume(){super.onResume();player.visible(true);if(resumed)load();resumed=true;}
    @Override protected void onPause(){player.visible(false);super.onPause();}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("category",category);out.putInt("days",days);out.putInt("page",page);out.putString("selected",selected);ArrayList<String> keys=new ArrayList<>(positions.keySet());long[] values=new long[keys.size()];for(int n=0;n<keys.size();n++)values[n]=positions.get(keys.get(n));out.putStringArrayList("positionKeys",keys);out.putLongArray("positions",values);}
    private void load(){loaded=false;error="";int request=++generation;FavoriteSoundRows.Filter filter=new FavoriteSoundRows.Filter(days,category);int requested=page;Records.Factory source=records;Context app=getApplicationContext();render();worker.execute(()->{try(Store store=source.open(app)){FavoriteSoundRows.Page result=FavoriteSoundRows.read(app,store,filter,requested,System.currentTimeMillis());runOnUiThread(()->{if(isDestroyed()||request!=generation)return;data=result;Set<String> visible=new HashSet<>();for(FavoriteSoundRows.Item item:result.items)visible.add(item.row.key);positions.keySet().retainAll(visible);if(!visible.contains(selected))selected="";page=result.page;category=filter.category;days=filter.days;loaded=true;busy=false;render();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;error="Favorite sounds could not be loaded.";loaded=true;busy=false;render();});}});}
    private void filter(String value,int range){player.stop();selected="";positions.clear();category=value;days=range;page=0;notice="";load();}
    private void dates(){player.stop();String[] labels={"All dates","Past 7 days","Past 30 days"};int[] values={0,7,30};dialog=SleepPicker.choices(this,"Favorite dates",labels,days==7?1:days==30?2:0,n->filter(category,values[n]));}
    private void options(){player.stop();dialog=new Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=Design.col(this);Design.pad(panel,22,22);panel.setBackground(Design.shape(this,Design.CREAM,22));Design.text(panel,"Favorite sounds",22,600,Design.INK);Design.space(panel,12);LinearLayout other=Design.item(panel,category.equals("noise")?"check":"wave","Other sounds",null,null);other.setSelected(category.equals("noise"));other.setContentDescription("Other sounds");other.setFocusable(true);other.setBackground(Design.touch(this,category.equals("noise")?Design.SOFT:Color.TRANSPARENT,12));other.setOnClickListener(v->{dialog.dismiss();filter("noise",days);});Design.item(panel,"calendar","Dates",days==0?"All dates":"Past "+days+" days",()->{dialog.dismiss();dates();});Design.button(panel,"Cancel",false,dialog::dismiss);dialog.setContentView(panel);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),Design.dp(this,420)),-2);}
    private void render(){bindings.clear();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);LinearLayout header=RecordUi.header(body,"Favorites",this::finish);RecordUi.headerAction(header,"calendar","Filter favorite dates",this::dates);RecordUi.headerAction(header,"more","Favorite sound options",this::options);if(!loaded){Design.space(body,24);Design.text(body,"Loading favorite sounds…",15,400,Design.MUTED);return;}if(!error.isEmpty()){Design.space(body,24);Design.text(body,error,16,400,Design.MUTED);Design.button(body,"Try again",true,this::load);return;}
        Design.space(body,8);Design.text(body,(days==0?"All dates":"Past "+days+" days")+" · "+data.total+" favorite"+(data.total==1?"":"s"),14,400,Design.MUTED);Design.space(body,16);LinearLayout tabs=Design.row(this);String[] keys={"all","snoring","speech"},titles={"All","Snoring","Speech"};for(int n=0;n<keys.length;n++){String key=keys[n],title=titles[n]+" ("+data.count(key)+")";TextView tab=Design.text(this,title,13,category.equals(key)?600:400,category.equals(key)?Design.CREAM:Design.INK);tab.setGravity(Gravity.CENTER);tab.setBackground(Design.touch(this,category.equals(key)?Design.BROWN:Design.SOFT,12));tab.setSelected(category.equals(key));tab.setContentDescription(title);tab.setFocusable(true);tab.setOnClickListener(v->filter(key,days));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Design.dp(this,48),1);if(n>0)lp.leftMargin=Design.dp(this,8);tabs.addView(tab,lp);}body.addView(tabs);Design.space(body,14);
        if(category.equals("noise")){Design.text(body,"Other sounds",16,600,Design.INK);Design.space(body,10);}if(!notice.isEmpty()){Design.text(body,notice,13,500,Design.BROWN);Design.space(body,8);}if(data.items.isEmpty()){Design.space(body,30);Design.text(body,data.count("all")==0&&days==0?"No favorite sounds yet":"No favorites in this view",22,600,Design.INK);Design.space(body,10);Design.text(body,data.count("all")==0&&days==0?"Tap a heart in a night's sound events to keep a favorite.":"Choose another date range or category.",14,400,Design.MUTED);if(days!=0||!category.equals("all"))Design.button(body,"Show all favorites",false,()->filter("all",0));return;}
        String previous="";for(FavoriteSoundRows.Item item:data.items){String date=RecordUi.date(item.row.start,item.night.zone());if(!date.equals(previous)){Design.space(body,10);Design.text(body,date,13,600,Design.BROWN);Design.space(body,6);previous=date;}add(body,item);}if(page>0||data.older()){Design.space(body,14);LinearLayout paging=Design.row(this);if(page>0)pageButton(paging,"Newer",()->changePage(page-1));if(data.older())pageButton(paging,"Older",()->changePage(page+1));body.addView(paging);Design.text(body,"Page "+(page+1),12,400,Design.MUTED);}Design.space(body,20);
    }
    private void changePage(int next){player.stop();selected="";positions.clear();page=next;load();}
    private Drawable background(SoundEventRows.Row row){LayerDrawable layers=new LayerDrawable(new Drawable[]{Design.shape(this,selected.equals(row.key)?Design.SOFT:Color.TRANSPARENT,16),Design.shape(this,row.category.equals("speech")?0xffad82ef:0xffaa6538,2)});layers.setLayerSize(1,Design.dp(this,2),Design.dp(this,32));layers.setLayerGravity(1,Gravity.START|Gravity.TOP);layers.setLayerInset(1,0,Design.dp(this,12),0,0);return layers;}
    private void pageButton(LinearLayout row,String label,Runnable action){Button button=Design.button(row,label,false,action);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Design.dp(this,54),1);lp.setMargins(Design.dp(this,3),0,Design.dp(this,3),0);button.setLayoutParams(lp);}
    private void add(LinearLayout body,FavoriteSoundRows.Item item){SoundEventRows.Row row=item.row;LinearLayout card=Design.col(this);Design.pad(card,8,12);LinearLayout head=Design.row(this);TextView time=Design.text(this,RecordUi.preciseClock(this,row.start,item.night.zone()),12,400,Design.MUTED);head.addView(time,new LinearLayout.LayoutParams(Design.dp(this,84),-2));LinearLayout copy=Design.col(this);if(row.event==null||item.outside){Design.text(copy,row.title,14,600,Design.INK);}else{LinearLayout label=Design.row(this);TextView name=Design.text(this,row.title,14,600,Design.INK);label.addView(name,new LinearLayout.LayoutParams(0,-2,1));label.addView(new Design.Icon(this,"tag",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,18),Design.dp(this,18)));label.setMinimumHeight(Design.dp(this,48));label.setBackground(Design.touch(this,Color.TRANSPARENT,8));label.setFocusable(true);label.setContentDescription("Correct label "+row.key);label.setOnClickListener(v->{player.stop();startActivity(SoundLabelActivity.intent(this,row,item.night));});copy.addView(label);}Design.space(copy,5);Design.text(copy,row.duration>0?RecordUi.duration(row.duration):"Duration unavailable",12,400,Design.MUTED);head.addView(copy,new LinearLayout.LayoutParams(0,-2,1));View heart=Design.iconButton(this,"heartFilled","Unfavorite "+row.key,()->unfavorite(row));heart.setSelected(true);RecordUi.enabled(heart,!busy);head.addView(heart,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));head.addView(Design.iconButton(this,"chevron","Open night "+row.key,()->{player.stop();startActivity(RecordUi.intent(this,SoundEventsActivity.class).putExtra("record",item.night.id));}),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));card.addView(head);
        if(row.target==null){TextView missing=Design.text(card,row.audioError.isEmpty()?"Audio not recorded":row.audioError,12,400,Design.MUTED);missing.setPadding(Design.dp(this,84),Design.dp(this,10),0,0);card.setBackground(background(row));}else{Design.space(card,10);LinearLayout audio=Design.row(this);FrameLayout play=new FrameLayout(this);play.setFocusable(true);play.setOnClickListener(v->{selected=row.key;player.toggle(row.target,positions.getOrDefault(row.key,0L));});audio.addView(play,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));ClipWaveView wave=new ClipWaveView(this,row.peaks,row.category.equals("speech")?0xff9262df:Design.BROWN,row.category.equals("speech")?0xffc3a4f4:0xffcfb69f);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,Design.dp(this,42),1);wp.leftMargin=Design.dp(this,12);audio.addView(wave,wp);card.addView(audio);LinearLayout progress=Design.row(this);TextView elapsed=Design.text(this,"0:00",11,400,Design.MUTED);progress.addView(elapsed);ClipSeekView seek=new ClipSeekView(this,row.target.duration(),position->{selected=row.key;positions.put(row.key,position);if(playback!=null&&playback.key.equals(row.key))player.seek(position);else{player.stop();selected=row.key;positions.put(row.key,position);for(Binding binding:bindings)update(binding);}});LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,Design.dp(this,48),1);sp.setMargins(Design.dp(this,6),0,Design.dp(this,6),0);progress.addView(seek,sp);progress.addView(Design.text(this,clock(row.duration),11,400,Design.MUTED));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,-2);pp.leftMargin=Design.dp(this,60);card.addView(progress,pp);TextView failure=Design.text(card,"",12,400,Design.BROWN);failure.setVisibility(View.GONE);Binding binding=new Binding(row,card,play,wave,seek,elapsed,progress,failure);bindings.add(binding);update(binding);}body.addView(card);Design.space(body,4);Design.line(body);Design.space(body,4);}
    private void unfavorite(SoundEventRows.Row row){if(busy)return;busy=true;player.stop();for(Binding binding:bindings)update(binding);Records.Factory source=records;Context app=getApplicationContext();worker.execute(()->{try(Store store=source.open(app)){if(row.event!=null)SoundClips.favoriteEvent(store,row.event,false);else SoundClips.favorite(store,row.clip,false);runOnUiThread(()->{if(!isDestroyed()){notice="Removed from favorites.";load();}});}catch(Exception failure){runOnUiThread(()->{if(!isDestroyed()){busy=false;notice="Could not remove this favorite. Try again.";load();}});}});}
    private static String clock(long value){long seconds=Math.max(0,value/1000);return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    private void playback(ClipReviewPlayer.State value){playback=value;if(!value.key.isEmpty()){selected=value.key;positions.put(value.key,value.position);}for(Binding binding:bindings)update(binding);}
    private void update(Binding binding){SoundEventRows.Row row=binding.row;boolean current=playback!=null&&playback.key.equals(row.key),playing=current&&(playback.phase==ClipReviewPlayer.Phase.PLAYING||playback.phase==ClipReviewPlayer.Phase.READY||playback.phase==ClipReviewPlayer.Phase.LOADING);long position=current?playback.position:positions.getOrDefault(row.key,0L);String icon=playing?"pause":"play";if(!icon.equals(binding.icon)){binding.icon=icon;binding.play.removeAllViews();binding.play.addView(new Design.Icon(this,icon,playing?Design.CREAM:Design.BROWN),new FrameLayout.LayoutParams(Design.dp(this,22),Design.dp(this,22),Gravity.CENTER));binding.play.setBackground(playing?Design.touch(this,Design.BROWN,26):Design.outline(this,Design.CREAM,Appearance.contrast(this)?Design.BROWN:0xffceb7a8,26));}binding.play.setContentDescription((playing?"Pause ":"Play ")+row.key);binding.card.setBackground(background(row));binding.wave.progress(position/(float)row.duration);binding.seek.position(position);binding.elapsed.setText(clock(position));binding.progress.setVisibility(selected.equals(row.key)?View.VISIBLE:View.GONE);boolean failed=current&&playback.phase==ClipReviewPlayer.Phase.ERROR;binding.error.setVisibility(failed?View.VISIBLE:View.GONE);binding.error.setText(failed?playback.error:"");}
    boolean awaitReaders(long timeout)throws InterruptedException{long start=System.currentTimeMillis();boolean readers=worker.awaitTermination(timeout,TimeUnit.MILLISECONDS);return readers&&port.awaitClosed(Math.max(1,timeout-(System.currentTimeMillis()-start)));}
    @Override protected void onDestroy(){generation++;if(dialog!=null)dialog.dismiss();unregisterReceiver(noisy);player.close();port.close();worker.shutdown();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    private static final class Binding {final SoundEventRows.Row row;final LinearLayout card;final FrameLayout play;final ClipWaveView wave;final ClipSeekView seek;final TextView elapsed,error;final View progress;String icon="";Binding(SoundEventRows.Row row,LinearLayout card,FrameLayout play,ClipWaveView wave,ClipSeekView seek,TextView elapsed,View progress,TextView error){this.row=row;this.card=card;this.play=play;this.wave=wave;this.seek=seek;this.elapsed=elapsed;this.progress=progress;this.error=error;}}
}
